// Reproducible offline CommonJS closure; no install, network or runtime node_modules.
import fs from 'node:fs';
import path from 'node:path';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
const root=path.resolve(import.meta.dirname,'../..'),modules=path.join(root,'obs-vmix/node_modules');
const hash=b=>createHash('sha256').update(b).digest('hex');
for(const [name,version]of [['qrcode','1.5.4'],['dijkstrajs','1.0.3']])if(JSON.parse(fs.readFileSync(path.join(modules,name,'package.json'))).version!==version)throw Error('Encoder dependency pin mismatch');
const nodes=[],ids=new Map();
function add(file){file=fs.realpathSync(file);if(ids.has(file))return ids.get(file);const relative=path.relative(modules,file).replaceAll('\\','/');if(!/^(?:qrcode\/lib\/core\/|dijkstrajs\/)/.test(relative))throw Error('Unexpected bundle dependency');const id=nodes.length;ids.set(file,id);const source=fs.readFileSync(file,'utf8'),node={id,path:relative,sha256:hash(source),source,deps:{}};nodes.push(node);const require=createRequire(file);for(const match of source.matchAll(/require\(['"]([^'"]+)['"]\)/g))node.deps[match[1]]=add(require.resolve(match[1]));return id;}
const entry=add(path.join(modules,'qrcode/lib/core/qrcode.js'));
const provenancePath=path.join(import.meta.dirname,'bundle-provenance.json');
if(fs.existsSync(provenancePath)){const previous=JSON.parse(fs.readFileSync(provenancePath));if(previous.modules.length!==nodes.length||nodes.some(n=>previous.modules.find(p=>p.path===n.path)?.sha256!==n.sha256))throw Error('Encoder source hash differs from pinned QA provenance');}
const closure='(function(){const modules={'+nodes.map(n=>JSON.stringify(n.id)+':[function(module,exports,require){\n'+n.source+'\n},'+JSON.stringify(n.deps)+']').join(',\n')+'},cache={};function load(id){if(cache[id])return cache[id].exports;const m=cache[id]={exports:{}};const [fn,deps]=modules[id];fn(m,m.exports,name=>{if(!Object.hasOwn(deps,name))throw Error("Dependency outside QR closure");return load(deps[name]);});return m.exports;}return load('+entry+');})()';
const license='FreeMix offline QR encoder: qrcode 1.5.4 and dijkstrajs 1.0.3\n\n'+fs.readFileSync(path.join(modules,'qrcode/license'),'utf8')+'\n\n'+fs.readFileSync(path.join(modules,'dijkstrajs/LICENSE.md'),'utf8');
const output='// Generated by qa-finalizacao/gtzip-qr/build-bundle.mjs. MIT notices accompany every converted QR title.\nexport function gtQrEncoderFactory(){return '+closure+';}\nexport const GT_QR_ENCODER="("+gtQrEncoderFactory.toString()+")()";\nexport const GT_QR_LICENSE='+JSON.stringify(license)+';\n';
fs.writeFileSync(path.join(root,'obs-vmix/ferramentas/gtzip-qr-bundle.mjs'),output);
fs.writeFileSync(path.join(import.meta.dirname,'bundle-provenance.json'),JSON.stringify({qrcode:'1.5.4',dijkstrajs:'1.0.3',entry,modules:nodes.map(({source,deps,...rest})=>rest),bundleSha256:hash(output),licenseSha256:hash(license)},null,2));
console.log(JSON.stringify({modules:nodes.length,bytes:Buffer.byteLength(output),sha256:hash(output)}));
